class Solution {
public:
    int maxNumberOfApples(vector<int>& weight) {
        sort(weight.begin(), weight.end());
        int total = 0;
        int count = 0;
        for (int x : weight) {
            if (total + x > 5000) {
                break;
            }
            total += x;
            ++count;
        }
        return count;
    }
};
